create table canton (
                        id smallint primary key,
                        nombre varchar(60) not null,
                        provincia varchar(30) not null,
                        zona_cafetalera varchar(30),
                        cabecera geometry(Point, 4326) not null,
                        constraint uq_canton_provincia_nombre unique (provincia, nombre),
                        constraint ck_canton_provincia check (provincia in (
                                                                            'San José', 'Alajuela', 'Cartago', 'Heredia', 'Guanacaste', 'Puntarenas', 'Limón')),
                        constraint ck_canton_zona_cafetalera check (zona_cafetalera in (
                                                                                        'Tarrazú', 'Valle Central', 'Valle Occidental', 'Tres Ríos',
                                                                                        'Orosi', 'Turrialba', 'Brunca', 'Guanacaste'))
);

create index idx_canton_provincia on canton (provincia);

